// 参数化基线：复数乘法 4 乘法器（16 位，free）
module top (
    input  wire               clk,
    input  wire               rst_n,
    input  wire               in_valid,
    output wire               in_ready,
    input  wire signed [15:0] a,
    input  wire signed [15:0] b,
    input  wire signed [15:0] c,
    input  wire signed [15:0] d,
    output reg                out_valid,
    input  wire               out_ready,
    output reg  signed [32:0] y_re,
    output reg  signed [32:0] y_im
);
    // EVOLVE-BLOCK-START
    // Gauss 复数乘法：只需 3 个乘法器（直接法需要 4 个）
    wire signed [16:0] p = a + b, q = d - c, r = c + d;
    wire signed [32:0] k1 = c * p, k2 = a * q, k3 = b * r;
    assign in_ready = !out_valid || out_ready;
    always @(posedge clk) begin
        if (!rst_n) begin
            out_valid <= 1'b0; y_re <= 0; y_im <= 0;
        end else begin
            if (out_valid && out_ready) out_valid <= 1'b0;
            if (in_valid && in_ready) begin
                y_re <= k1 - k3;   // = a*c - b*d
                y_im <= k1 + k2;   // = a*d + b*c
                out_valid <= 1'b1;
            end
        end
    end
    // EVOLVE-BLOCK-END
endmodule

